/**
 * @brief   Function for initializing the ble stack
 * @param   role                Indicate the role for ble stack.
 *                              role = 1: ble peripheral    @TKL_BLE_ROLE_SERVER
 *                              role = 2: ble central       @TKL_BLE_ROLE_CLIENT
 * @return  SUCCESS             Initialized successfully.
 *          ERROR
 * */
OPERATE_RET tkl_ble_stack_init(uint8_t role)
{
    // --- BEGIN: user implements ---
    if ((role & TKL_BLE_ROLE_SERVER) == 0U) return OPRT_NOT_SUPPORTED;
    if (s_ble_initialized) return OPRT_OK;
    if (vw553_device_init() != OPRT_OK || vw553_device_negotiate(VW553_BLE_TIMEOUT_MS) != OPRT_OK) {
        return OPRT_COM_ERROR;
    }
    if (!s_ble_subscribed) {
        if (vw553_device_subscribe(ble_device_event, NULL) != OPRT_OK) return OPRT_COM_ERROR;
        s_ble_subscribed = true;
    }
    /* H77 can reboot while the independently powered module keeps advertising.
     * Close its old BLE session before creating a fresh local adapter session.
     * Module commands acknowledge only after disable/enable has completed. */
    if (ble_execute("AT+BLEDISABLE", NULL, 0U) != OPRT_OK ||
        ble_execute("AT+BLEENABLE", NULL, 0U) != OPRT_OK ||
        ble_execute("AT+BLEDADATRANS=1", NULL, 0U) != OPRT_OK) return OPRT_COM_ERROR;
    s_ble_initialized = true;
    ble_gap_event(TKL_BLE_EVT_STACK_INIT, TKL_BLE_GATT_INVALID_HANDLE, 0);
    return OPRT_OK;
    // --- END: user implements ---
}

/**
 * @brief   Function for de-initializing the ble stack features
 * @param   role                 Indicate the role for ble stack.
 *                               role = 1: ble peripheral
 *                               role = 2: ble central
 * @return  SUCCESS             Deinitialized successfully.
 *          ERROR
 * */
OPERATE_RET tkl_ble_stack_deinit(uint8_t role)
{
    // --- BEGIN: user implements ---
    (void)role;
    if (!s_ble_initialized) return OPRT_OK;
    (void)ble_execute("AT+BLEADVSTOP=0", NULL, 0U);
    (void)ble_execute("AT+BLEDISABLE", NULL, 0U);
    s_ble_initialized = false;
    ble_gap_event(TKL_BLE_EVT_STACK_DEINIT, TKL_BLE_GATT_INVALID_HANDLE, 0);
    return OPRT_OK;
    // --- END: user implements ---
}

