/**
 * @brief   Start advertising
 * @param   [in] p_adv_params : pointer to advertising parameters
 * @return  SUCCESS
 *  ERROR
 * */
OPERATE_RET tkl_ble_gap_adv_start(TKL_BLE_GAP_ADV_PARAMS_T const *p_adv_params)
{
    // --- BEGIN: user implements ---
    char command[64];
    unsigned interval = 0x00A0U;
    unsigned channels = p_adv_params ? p_adv_params->adv_channel_map : 0x07U;
    if (!s_ble_initialized) return OPRT_RESOURCE_NOT_READY;
    if (p_adv_params && p_adv_params->adv_type != TKL_BLE_GAP_ADV_TYPE_CONN_SCANNABLE_UNDIRECTED) {
        return OPRT_NOT_SUPPORTED;
    }
    if (p_adv_params) {
        /* TAL passes milliseconds while the VW553 AT command takes 0.625 ms
         * units. 30 ms must become 0x30, not 0x1E which is below the BLE
         * legacy minimum and makes the controller reject advertising. */
        uint32_t interval_ms = p_adv_params->adv_interval_min;
        interval = (interval_ms * 1000U + 312U) / 625U;
        if (interval < 0x20U) interval = 0x20U;
        if (interval > 0x4000U) interval = 0x4000U;
        VW553_LOG("BLE adv interval %lums units=0x%X", (unsigned long)interval_ms, interval);
    }
    int written = snprintf(command, sizeof(command), "AT+BLEADVSTART=0,%X,%X", interval, channels);
    if (written < 0 || (size_t)written >= sizeof(command)) return OPRT_INVALID_PARM;
    OPERATE_RET result = ble_execute(command, NULL, 0U);
    if (result == OPRT_OK) ble_gap_event(TKL_BLE_GAP_EVT_ADV_STATE, TKL_BLE_GATT_INVALID_HANDLE, 0);
    return result;
    // --- END: user implements ---
}

