/**
 * @brief   Notify an attribute value.
 * @param   [in] conn_handle    Connection handle.
 * @param   [in] char_handle    Attribute handle.
 *          [in] p_data         Notify Values
 *          [in] length         Value Length
 * @return  SUCCESS
 *          ERROR
 * */
OPERATE_RET tkl_ble_gatts_value_notify(uint16_t conn_handle, uint16_t char_handle, uint8_t *p_data, uint16_t length)
{
    // --- BEGIN: user implements ---
    if (!s_ble_initialized || !p_data || !length || char_handle != VW553_BLE_NOTIFY_HANDLE || conn_handle > UINT8_MAX) {
        return OPRT_INVALID_PARM;
    }
    char command[48];
    int written = snprintf(command, sizeof(command), "AT+BLEDADATRANSSEND=%u,%u", (unsigned)conn_handle,
                           (unsigned)length);
    if (written < 0 || (size_t)written >= sizeof(command)) return OPRT_INVALID_PARM;
    OPERATE_RET result = OPRT_COM_ERROR;
    for (unsigned attempt = 0U; attempt < 3U; ++attempt) {
        result = ble_execute(command, p_data, length);
        if (result == OPRT_OK) return OPRT_OK;
        /* The controller rejects the next notification while the previous one
         * is still waiting for a connection event (interval 0x15 here), which
         * used to abort the provisioning response mid-session. Retry instead
         * of surfacing the transient refusal. */
        if (attempt + 1U < 3U) vTaskDelay(pdMS_TO_TICKS(30U) ? pdMS_TO_TICKS(30U) : 1U);
    }
    return result;
    // --- END: user implements ---
}

/**
 * @brief   Indicate an attribute value.
 * @param   [in] conn_handle    Connection handle.
 * @param   [in] char_handle    Attribute handle.
 *          [in] p_data         Notify Values
 *          [in] length         Value Length
 * @return  SUCCESS
 *          ERROR
 * */
OPERATE_RET tkl_ble_gatts_value_indicate(uint16_t conn_handle, uint16_t char_handle, uint8_t *p_data, uint16_t length)
{
    // --- BEGIN: user implements ---
    return tkl_ble_gatts_value_notify(conn_handle, char_handle, p_data, length);
    // --- END: user implements ---
}

